#!/usr/bin/env python3
# -*- coding: utf-8 -*-
# patch_engajamento_meta.py -- 1o comentario automatico no meta_uploader.
# Idempotente, backup, py_compile, restaura se falhar. Rode na VPS:
#   cd ~/jarvis && .venv/bin/python patch_engajamento_meta.py
import base64, py_compile, shutil, sys, time
from pathlib import Path

ALVO = Path(__file__).resolve().parent / "agents/meta_uploader.py"
PARES = [('', ''), ('', ''), ('', ''), ('', '')]

def main():
    if not ALVO.exists():
        print(f"❌ nao achei {ALVO}"); return 1
    txt = ALVO.read_text(encoding="utf-8").replace("\r\n", "\n")
    pares = [(base64.b64decode(o).decode(), base64.b64decode(n).decode()) for o, n in PARES]

    ja = sum(1 for _, n in pares if n in txt)
    if ja == len(pares):
        print("✅ JA APLICADO — nada a fazer."); return 0

    novo = txt
    for old_blk, new_blk in pares:
        if new_blk in novo:
            continue
        if old_blk not in novo:
            print("❌ ABORTADO: bloco esperado nao encontrado (VPS divergente):")
            print("   " + old_blk.strip().splitlines()[0][:90]); return 2
        if novo.count(old_blk) != 1:
            print("❌ ABORTADO: bloco ambiguo (aparece != 1x)"); return 2
        novo = novo.replace(old_blk, new_blk)

    bak = ALVO.with_suffix(ALVO.suffix + ".bak_" + time.strftime("%Y%m%d_%H%M%S"))
    shutil.copy2(ALVO, bak)
    ALVO.write_text(novo, encoding="utf-8")
    try:
        py_compile.compile(str(ALVO), doraise=True)
    except Exception as e:
        shutil.copy2(bak, ALVO)
        print(f"❌ py_compile falhou, RESTAUREI o backup: {e}"); return 3
    print(f"✅ APLICADO. backup: {bak.name}")
    print("   Ligue com: echo 'ENGAJAR_COMENTARIO=1' >> ~/jarvis/.env  (e reinicie o jarvis)")
    return 0

if __name__ == "__main__":
    sys.exit(main())
